    T pivmin = /* minimum pivot value */;

    count_a = sturm_count(n, D, E, pivmin, a);
    count_b = sturm_count(n, D, E, pivmin, b);

    // Bisection loop
    while(true)
    {
        // Compute tolerance
        T tmp = std::max(std::abs(a), std::abs(b));
        atol = 2 * tmp * eps + abstol;

        // Check convergence
        if(b - a <= atol)
            break;

        // Bisect interval
        c = (a + b) / 2;
        count_c = sturm_count(n, D, E, pivmin, c);

